steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams(filter: {name: {eq: \"Web Platform\"}}) {
          nodes {
            id
            name
            key
            cycles {
              nodes {
                id
                name
                number
              }
            }
          }
        }
        users(filter: {name: {contains: \"Priya Nair\"}}) {
          nodes {
            id
            name
            email
          }
        }
      }
    "
  }'
